function validate([root, target]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each node value is a whole number from 0 to 10^9.';
  if (target < -1e9 || target > 1e9) return 'target is between -10^9 and 10^9.';
  // Rebuild the links from the level order, then the in-order values must rise strictly.
  const queue = [{ val: root[0], left: null, right: null }];
  let next = 1;
  for (let q = 0; q < queue.length && next < root.length; q++) {
    for (const side of ['left', 'right']) {
      if (next >= root.length) break;
      const value = root[next++];
      if (value === null) continue;
      const child = { val: value, left: null, right: null };
      queue[q][side] = child;
      queue.push(child);
    }
  }
  if (next < root.length) return 'Every value after the root needs a parent node.';
  const stack = [];
  let node = queue[0], last = -Infinity;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    if (node.val <= last) return 'The tree must be a binary search tree with distinct values.';
    last = node.val;
    node = node.right;
  }
  return null;
}

