function closestValue(root, target) {
  let closest = root.val;
  let node = root;

  while (node) {
    const gap = Math.abs(node.val - target);
    const bestGap = Math.abs(closest - target);
    if (gap < bestGap || (gap === bestGap && node.val < closest)) {
      closest = node.val;
    }
    if (target < node.val) {
      node = node.left;
    } else {
      node = node.right;
    }
  }
  return closest;
}

