function closestValue(root, target) {
  // Check every value in the tree, ignoring the ordering.
  const values = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    values.push(node.val);
    stack.push(node.left, node.right);
  }
  let best = values[0];
  for (const value of values) {
    const mine = Math.abs(value - target), theirs = Math.abs(best - target);
    if (mine < theirs || (mine === theirs && value < best)) best = value;
  }
  return best;
}

