function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const small = size === 'small';
  const count = small ? 1 + pick(10) : 900 + pick(80);
  const top = small && rand() < 0.8 ? 20 : 1e9;
  // Distinct values inserted in random order give a random BST shape.
  const seen = new Set();
  const order = [];
  while (order.length < count) {
    const value = pick(top + 1);
    if (seen.has(value)) continue;
    seen.add(value);
    order.push(value);
  }
  // Sorted insertion order makes a chain.
  if (small && rand() < 0.2) { const rising = rand() < 0.5; order.sort((a, b) => (rising ? a - b : b - a)); }
  let root = null;
  for (const value of order) {
    const node = { val: value, left: null, right: null };
    if (!root) { root = node; continue; }
    let at = root;
    for (;;) {
      const side = value < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  // Targets: whole numbers, exact halves (possible ties) and decimals, sometimes out of range.
  const style = rand();
  let target;
  if (style < 0.1) target = rand() < 0.5 ? -1e9 : 1e9;
  else if (style < 0.35) target = order[pick(order.length)];
  else if (style < 0.6) target = (pick(2 * top + 6) - 4) / 2;
  else target = Math.round((rand() * (top + 6) - 3) * 1e6) / 1e6;
  return [out, Math.min(1e9, Math.max(-1e9, target))];
}
